  "Enzo": {
   "sources": [
    "https://github.com/nimda5/baltic-widgets/blob/codex/namedays-round4/research/namedays/round142-notes.json"
   ],
   "keep": true,
   "text": {
    "lv": [
     "Enzo varētu būt itāļu vārds Enzo; to saista ar Heinz (Heinrihs). Vārdu Henrijs parasti skaidro ar ģermāņu heim + rīhhi — «mājas + valdnieks». Tas ir pieņēmums: zināms tikai vārda izcelsmes virziens, bet ne tā tuvākā cilme."
    ],
    "ru": [
     "Энцо, вероятно, итальянское имя Enzo; его связывают с Heinz (Генрих). Имя Henrijs обычно объясняют через германское heim + rīhhi — «дом + правитель». Это предположение: известно лишь общее направление происхождения имени, но не его ближайший источник."
    ],
    "en": [
     "Enzo is probably the Italian name Enzo, linked with Heinz (Henry). Henrijs is usually explained from Germanic heim + rīhhi, “home + ruler”. This is a hypothesis: only the general origin of the name is known, not its immediate source."
    ],
    "lt": [
     "Enzo greičiausiai yra itališkas vardas Enzo, siejamas su Heinz (Henrikas). Vardas Henrijs paprastai aiškinamas germanų heim + rīhhi („namai + valdovas“). Tai prielaida: žinoma tik bendra vardo kilmės kryptis, bet ne artimiausias šaltinis."
    ],
    "et": [
     "Enzo on tõenäoliselt itaalia nimi Enzo, mida seostatakse nimega Heinz (Heinrich). Nime Henrijs seletatakse tavaliselt germaani sõnaga heim + rīhhi ‘kodu + valitseja’. See on oletus: teada on vaid nime üldine päritolu, mitte selle lähim allikas."
    ]
   }
  },
